INSERT INTO `SERVMASK_PREFIX_posts` VALUES (58,1,'2024-06-19 09:53:01','2024-06-19 07:53:01','<!-- wp:paragraph -->\n<p>Timár Attilának hívnak. 2005. 10. hó 21.-én születtem Miskolcon. Általános iskolai tanulmányaimat  a <strong>bekecsi II. Rákóczi Ferenc Informatikai és Matematikai Általános Iskolában</strong> végeztem. 2021 szeptemberében kezdtem meg tanulmányaimat itt a <strong>Miskolci SZC Bláthy Ottó Villamos Ipari Technikumban. Jelenleg Ipari Informatika</strong> szakirányon vagyok. Terveim között van egy mérnöki cím megszerzése egyetemen.</p>\n<!-- /wp:paragraph -->','Magamról','','inherit','closed','closed','','17-revision-v1','','','2024-06-19 09:53:01','2024-06-19 07:53:01','',17,'https://192.168.188.6/timara/?p=58',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (62,1,'2024-06-19 10:11:58','2024-06-19 08:11:58','<!-- wp:paragraph -->\n<p>Timár Attilának hívnak. 2005. 10. hó 21.-én születtem Miskolcon. Általános iskolai tanulmányaimat a <strong>Bekecsi II. Rákóczi Ferenc Informatikai és Matematikai Általános Iskolában</strong> végeztem. 2021 szeptemberében kezdtem meg tanulmányaimat itt a <strong>Miskolci SZC Bláthy Ottó Villamos Ipari Technikumban. Jelenleg Ipari Informatika</strong> szakirányon vagyok. Terveim között van egy mérnöki cím megszerzése egyetemen.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Számott tevően nem dolgoztam sehol, de képes vagyok önállóan és csapatban is dolgozni</p>\n<!-- /wp:paragraph -->','Magamról','','inherit','closed','closed','','17-revision-v1','','','2024-06-19 10:11:58','2024-06-19 08:11:58','',17,'https://192.168.188.6/timara/?p=62',0,'revision','',0);
