INSERT INTO `SERVMASK_PREFIX_posts` VALUES (98,1,'2024-06-20 09:03:25','2024-06-20 07:03:25','<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">villamos tér</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":97,\"width\":\"418px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"right\"} -->\n<figure class=\"wp-block-image alignright size-large is-resized\"><img src=\"https://192.168.188.6/timara/wp-content/uploads/2024/06/image-1-1024x490.png\" alt=\"\" class=\"wp-image-97\" style=\"width:418px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p>ez a rajz volt az első ami lényegesseben vetünk a villamos térből. Itt néztük meg hogy az elekton hiányos területek és az elektron többlettel rendelkező területek hozznak létre villamos teret melynek irányát az E (elektrommos térerősség rányvektora) jelöli. Most két lemez közötti villamos teret mutattam de ez vezetékben is igy néz ki.</p>\n<!-- /wp:paragraph -->','villamos alapismeretek','','inherit','closed','closed','','21-revision-v1','','','2024-06-20 09:03:25','2024-06-20 07:03:25','',21,'https://192.168.188.6/timara/?p=98',0,'revision','',0);
