INSERT INTO `SERVMASK_PREFIX_posts` VALUES (186,1,'2024-06-21 08:37:33','2024-06-21 06:37:33','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {\"ordered\":true} -->\n<ol></ol>\n<!-- /wp:list -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.mühelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak. Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Rácsszerkezetek:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 08:37:33','2024-06-21 06:37:33','',19,'http://192.168.188.6/timara/?p=186',0,'revision','',0);
