INSERT INTO `SERVMASK_PREFIX_posts` VALUES (260,1,'2024-06-21 11:19:51','2024-06-21 09:19:51','','image-32','','inherit','open','closed','','image-32','','','2024-06-21 11:19:51','2024-06-21 09:19:51','',19,'http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png',0,'attachment','image/png',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (261,1,'2024-06-21 11:20:07','2024-06-21 09:20:07','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":249,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=249\",\"mediaType\":\"image\",\"mediaWidth\":37} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-28.png\" alt=\"\" class=\"wp-image-249 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":256,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=256\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-30.png\" alt=\"\" class=\"wp-image-256 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:20:07','2024-06-21 09:20:07','',19,'http://192.168.188.6/timara/?p=261',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (262,1,'2024-06-21 11:20:26','2024-06-21 09:20:26','','image-33','','inherit','open','closed','','image-33','','','2024-06-21 11:20:26','2024-06-21 09:20:26','',19,'http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png',0,'attachment','image/png',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (263,1,'2024-06-21 11:20:38','2024-06-21 09:20:38','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":249,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=249\",\"mediaType\":\"image\",\"mediaWidth\":37} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-28.png\" alt=\"\" class=\"wp-image-249 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:image {\"id\":262,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262\"/></figure>\n<!-- /wp:image -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:20:38','2024-06-21 09:20:38','',19,'http://192.168.188.6/timara/?p=263',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (264,1,'2024-06-21 11:21:10','2024-06-21 09:21:10','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":249,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=249\",\"mediaType\":\"image\",\"mediaWidth\":46} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:46% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-28.png\" alt=\"\" class=\"wp-image-249 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:image {\"id\":262,\"width\":\"308px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262\" style=\"width:308px;height:auto\"/></figure>\n<!-- /wp:image -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:21:10','2024-06-21 09:21:10','',19,'http://192.168.188.6/timara/?p=264',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (265,1,'2024-06-21 11:21:43','2024-06-21 09:21:43','','image-34','','inherit','open','closed','','image-34','','','2024-06-21 11:21:43','2024-06-21 09:21:43','',19,'http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png',0,'attachment','image/png',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (266,1,'2024-06-21 11:21:52','2024-06-21 09:21:52','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":265,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=265\",\"mediaType\":\"image\",\"mediaWidth\":46} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:46% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:image {\"id\":265,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265\"/></figure>\n<!-- /wp:image -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:21:52','2024-06-21 09:21:52','',19,'http://192.168.188.6/timara/?p=266',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (267,1,'2024-06-21 11:22:03','2024-06-21 09:22:03','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":265,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=265\",\"mediaType\":\"image\",\"mediaWidth\":46} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 46%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:40% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:image {\"id\":265,\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265\"/></figure>\n<!-- /wp:image -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:22:03','2024-06-21 09:22:03','',19,'http://192.168.188.6/timara/?p=267',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (268,1,'2024-06-21 11:22:38','2024-06-21 09:22:38','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":265,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=265\",\"mediaType\":\"image\",\"mediaWidth\":46} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:46% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:22:38','2024-06-21 09:22:38','',19,'http://192.168.188.6/timara/?p=268',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (269,1,'2024-06-21 11:24:13','2024-06-21 09:24:13','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":265,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=265\",\"mediaType\":\"image\",\"mediaWidth\":46} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:46% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 40%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Gyakorlat</h1>\n<!-- /wp:heading -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:24:13','2024-06-21 09:24:13','',19,'http://192.168.188.6/timara/?p=269',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (270,1,'2024-06-21 11:30:55','2024-06-21 09:30:55','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":265,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=265\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:40% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":42} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Gyakorlat</h1>\n<!-- /wp:heading -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:30:55','2024-06-21 09:30:55','',19,'http://192.168.188.6/timara/?p=270',0,'revision','',0);
INSERT INTO `SERVMASK_PREFIX_posts` VALUES (271,1,'2024-06-21 11:31:03','2024-06-21 09:31:03','<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Elmélet</h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">rajzfajták a gépészetben</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.Elvi rajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Technológiai folyamatábra</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Technológiai kapcsolási rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hidraulikus kapcsolási terv</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Izometrikus csőtervek</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>2. Alkatrész rajzok</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Összeállítási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>3.Műhelyrajz</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elrendezési rajz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Karbantartási rajz</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Metallográfia alapfogalmak</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>1.fémek szerkezete</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Szilárd állapotban minden fém kristályokból épül fel. A fémkristályok több atomból (ionból) állnak, amelyek szabályos idomokat alkotnak.</strong> Ezeket az idomokat rácselemenek vagy elemi cellának nevezzük. A szabályosan ismétlődő rácselemekből álló szerkezet a rácsszerkezet. A kristályrácsot az úgynevezett fémes kötés tartja össze.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Rácsszerkezetek</strong>:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-group\"><!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li>Elemi cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Térközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Lapközepes cella</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Tetragonális kristályrács</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Hexagonális kristályrács</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:image {\"id\":185,\"width\":\"409px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-15.png\" alt=\"\" class=\"wp-image-185\" style=\"width:409px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:image {\"id\":187,\"width\":\"361px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-16.png\" alt=\"\" class=\"wp-image-187\" style=\"width:361px;height:auto\"/><figcaption class=\"wp-element-caption\">Különbőző anyagok kristélyrács szerkezetei</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Fémkohászat</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fémek csoportositása különbőző szempontokból</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alkáli fémek</strong>: a táblázat első oszlopában helyezkednek el. Jellemzőjük az alacsony olvasáspont, kis sűrűség, általában puhák.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Alkáli földfémek</strong>: a táblázat második oszlopában találhatók. Ezek a fémek keményebbek, mint az előző oszlopban lévők.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Rézcsoport</strong>: melyek jó vezető tulajdonságokkal bírnak, ennek alapján a villamos berendezésekben alkalmazzák főként ezeket a fémeket.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Vascsoport</strong>: elsősorban a jó mechanikai tulajdonságaikat használják ki a műszaki berendezésekben, de pl.: jó mágneses tulajdonságokkal rendelkeznek.</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Széncsoport</strong>: melyeket félfémeknek is neveznek. Ezeket az elemeket főként a villamosiparban félvezetők anyagaként alkalmazzák.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">olvadáspont alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Alacsony olvadáspontú fémek</strong>: 1000 celsius fok-tól kisebb</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Közepes olvadáspontú fémek</strong>: 1000 celsius fok és 2000 celsius fok között</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Magas olvadáspontú fémek</strong>:2000 celsius fok felett</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">sűrűség alapján</h4>\n<!-- /wp:heading -->\n\n<!-- wp:list -->\n<ul><!-- wp:list-item -->\n<li><strong>Könnyű fémek</strong>: sűrűségük kisebb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Nehéz fémek</strong>: sűrűségük nagyobb mint 4,5 kg/dm^3</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Nyers vas gyártás</h3>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":4} -->\n<h4 class=\"wp-block-heading\">Ércek</h4>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":193,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=193\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Mágneses vasérc</strong> (magnetit) </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\">~50-70% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed.jpg\" alt=\"\" class=\"wp-image-193 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":194,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=194\",\"mediaType\":\"image\",\"mediaWidth\":36,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:36% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-1-1024x755.jpg\" alt=\"\" class=\"wp-image-194 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Vörös vasérc</strong> (hematit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~40-60% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":195,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=195\",\"mediaType\":\"image\",\"mediaWidth\":42,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:auto 42%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"right\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-right\"><strong>Barna vasérc </strong>(limonit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"right\"} -->\n<p class=\"has-text-align-right\">~30-60% vastartalom</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-2.jpg\" alt=\"\" class=\"wp-image-195 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaId\":196,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=196\",\"mediaType\":\"image\",\"mediaWidth\":37,\"verticalAlignment\":\"center\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile is-vertically-aligned-center\" style=\"grid-template-columns:37% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-3-1018x1024.jpg\" alt=\"\" class=\"wp-image-196 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"placeholder\":\"Tartalom…\"} -->\n<p><strong>Pát vasérc</strong> (sziderit)</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>~20-40% vastartalom</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph {\"align\":\"left\"} -->\n<p class=\"has-text-align-left\"><strong>A vasérceket általában nem eredeti formájukban adagolják a nagyolvasztóba</strong>, hanem könnyebben redukálhatóvá, kedvező szemnagyságúvá és porozitásúvá alakítják, és még salakképző anyagot is kevernek hozzá. Ezt a műveletet agglomerálásnak nevezik.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Salak képző anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>Metallurgia</strong> – Fémekkel foglalkozó műszaki tudomány</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Érceikből történő előállításával, az így nyert fémek sajátságaival és további feldolgozásával foglalkozó tudományág; a kohászat tudománya. <strong>Kohósítás közben a vasérc meddőtartalma (nem hasznos elemek a vasércben) is megolvad, ebből lesz a salak</strong>. A salak kémiai összetétele igen fontos, mert a metallurgus – többek között – ezzel tudja befolyásolni a kéntelenítés folyamatát. <strong>A kéntelenítés azért fontos, mert a kén a vasban és az acélban is szennyező elem</strong>. A salak kémiai összetételét salakképzők adagolásával állítják be: <strong>a salakképző anyag többnyire mészkő és dolomit.</strong> Ha olyan zsugorítványt vagy pelletet használnak, amely már tartalmazza ezeket, akkor általában nem kell külön salakképző anyag (ezek az „önjáró ércek”).</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Tüzelő, Redukáló anyagok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p><strong>A nagyolvasztóban használatos tüzelő-redukálóanyag többnyire a koksz (szénből előállított tüzelőanyag)</strong>. A koksz egyrészt hőt, másrészt redukáló gázt fejleszt, harmadrészt karbonizálja (szénnel ötvözi) a vasat. <strong>A koksz C-tartalma több mint 85%, és annál jobb, ha minél kisebb (1% alatti) a kéntartalma</strong>. A koksz szerkezete erősen porózus, ami javítja a nagyolvasztóban elhelyezett elegyoszlop gázátjárhatóságát. Egyes esetekben brikettkokszot használnak, amit szurok kötőanyaggal állítanak elő.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>A kokszfelhasználás csökkentése érdekében külön redukálóanyagokat: szénhidrogéneket (földgáz, fűtőolaj), szénport stb. is használnak.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">A nagyolvasztó részei</h2>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":213,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=213\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/unnamed-4.jpg\" alt=\"\" class=\"wp-image-213 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:list {\"ordered\":true} -->\n<ol><!-- wp:list-item -->\n<li>meleg levegő befúvás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>olvasztó zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 1</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>redukáló zóna 2</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>előmelegítő zóna</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegy adagoló</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>torokgáz</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>elegyoszlop</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>salak és salakcsapoló nyílás</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>medence és a nyersvas csapolónyílása</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>távozó kohógáz</li>\n<!-- /wp:list-item --></ol>\n<!-- /wp:list --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési ábra</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">vonal típusok és jelentéseik</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":215,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=215\",\"mediaType\":\"image\",\"mediaWidth\":34} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:34% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-17.png\" alt=\"\" class=\"wp-image-215 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:image {\"id\":216,\"width\":\"507px\",\"height\":\"auto\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"style\":{\"color\":{\"duotone\":\"var:preset|duotone|grayscale\"}}} -->\n<figure class=\"wp-block-image size-large is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-18.png\" alt=\"\" class=\"wp-image-216\" style=\"width:507px;height:auto\"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Vetítési rendszer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:image {\"id\":219,\"width\":\"685px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-19.png\" alt=\"\" class=\"wp-image-219\" style=\"width:685px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:paragraph -->\n<p><strong>Európában használt vetítési rendszer áll körbe ölel egy alakzatot.</strong> Mi ezt a rajzott egy árnyékhoz hasonlítottuk egy dobozban és ezeket elég sokat is használtuk gyakorlaton mikor rajzolni kellet valamit, illetve az ágazati vizsgafeladatban is volt rajzolási feladat.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Méretvonal ábrázolása és főbb fajtái</h3>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":231,\"width\":\"654px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-20.png\" alt=\"\" class=\"wp-image-231\" style=\"width:654px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:image {\"id\":232,\"width\":\"653px\",\"height\":\"auto\",\"sizeSlug\":\"full\",\"linkDestination\":\"none\",\"align\":\"center\"} -->\n<figure class=\"wp-block-image aligncenter size-full is-resized\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-21.png\" alt=\"\" class=\"wp-image-232\" style=\"width:653px;height:auto\"/></figure>\n<!-- /wp:image -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Előrajzolás szerszámai</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rajztű</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":242,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=242\",\"mediaType\":\"image\",\"mediaWidth\":23} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:23% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-26.png\" alt=\"\" class=\"wp-image-242 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:group {\"layout\":{\"type\":\"flex\",\"orientation\":\"vertical\",\"verticalAlignment\":\"center\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">Rajztű anyaga lehet: szerszámacél vagy sárgaréz. Lehet különböző alakúak. pontos és éles volalakat húzhatunk meg vele.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Használatakor csak húzni szabad. (toláskor sérülhet a munkadarab. Húzás közben 30-35 fokos szögben kell megdönteni a könnyebb vonalhúzás érdekében</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Rugós körző</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":247,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=247\",\"mediaType\":\"image\",\"mediaWidth\":26} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 26%\"><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\">a körző lehet grafit, illetve acél hegyű is. működését segíti egy szabályzó-anya. a mozgó körzőszár a rugó elejétől a szabályzóanyához nyomódik. A körző a szabályzó-anya forgatásával állítjuk be</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-27.png\" alt=\"\" class=\"wp-image-247 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Pontozók</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":265,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=265\",\"mediaType\":\"image\",\"mediaWidth\":40} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\" style=\"grid-template-columns:40% auto\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-34.png\" alt=\"\" class=\"wp-image-265 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph {\"align\":\"center\",\"placeholder\":\"Tartalom…\"} -->\n<p class=\"has-text-align-center\"><strong>Anyaguk edzett szénacél, ezért nagyon kemény</strong>. A legkisebb szabványos hossza 100mm, 8mm-es átmérővel redelkezik. A legnagyobbé pedig 160mm hosszú, 18mm-es átmérő. 2 fajtája van vonalpontozó és furatpontozó</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A vonalpontozó</strong> 30-40 fokos csúcsszög alakú a hegye. nem hagy nagy nyomot ezért furatfészek készítésére nem alkalmas.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\"><strong>A furatpontozó</strong> 60 fokos csúcsszög alakú heggyel rendelkezik és nagy nyomot hagy ami a fúró vezetésére alkalmas.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fontosabb kalapácsok</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":255,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=255\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Asztalos kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">Nagy pontosságú szerszámok. mennyire pontos a fejtömeg széles tartományában - 100 - 800 gramm 50 grammos lépésekben - Az ütközési rész a legtöbb esetben tökéletesen lapos, a hátsó rész lehet körömhúzó vagy egyszerű ék.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-29.png\" alt=\"\" class=\"wp-image-255 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:media-text {\"mediaPosition\":\"right\",\"mediaId\":262,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=262\",\"mediaType\":\"image\",\"mediaWidth\":41} -->\n<div class=\"wp-block-media-text has-media-on-the-right is-stacked-on-mobile\" style=\"grid-template-columns:auto 41%\"><div class=\"wp-block-media-text__content\"><!-- wp:heading {\"textAlign\":\"center\",\"level\":4} -->\n<h4 class=\"wp-block-heading has-text-align-center\">Szintező kalapács</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\"} -->\n<p class=\"has-text-align-center\">A deformált óntermékek szintezésére, tetők, vízelvezető rendszerek és egyéb fémlemezekkel végzett műveletekre szánták. Általában gumiból vagy poliuretánból készülnek, de vannak olyan fémfejű modellek is, amelyek lágyabb anyagból cserélhető szerszámokkal vannak ellátva.</p>\n<!-- /wp:paragraph --></div><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-33.png\" alt=\"\" class=\"wp-image-262 size-full\"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"level\":3} -->\n<h3 class=\"wp-block-heading\">Fém és acelvonalzó</h3>\n<!-- /wp:heading -->\n\n<!-- wp:media-text {\"mediaId\":260,\"mediaLink\":\"http://192.168.188.6/timara/?attachment_id=260\",\"mediaType\":\"image\"} -->\n<div class=\"wp-block-media-text is-stacked-on-mobile\"><figure class=\"wp-block-media-text__media\"><img src=\"http://192.168.188.6/timara/wp-content/uploads/2024/06/image-32.png\" alt=\"\" class=\"wp-image-260 size-full\"/></figure><div class=\"wp-block-media-text__content\"><!-- wp:paragraph -->\n<p>Rajzoláshoz és kisebb mérésekhez ideális eszközök. Ezek használata nagyon egyszerű, a megmunkálásuknak köszönhetően pedig hosszú évekig is problémamentesen lehet használni.<br>Jellemzők: Rozsdamentes anyagból készülnek. Tartós mélynyomott skálával (Fekete). 1/2 és 1/1 mm kiosztással rendelkezik. A vonalzók 15cm-200cm hosszúságban<br>megtalálhatóak</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:media-text -->\n\n<!-- wp:heading {\"textAlign\":\"center\",\"level\":1} -->\n<h1 class=\"wp-block-heading has-text-align-center\">Gyakorlat</h1>\n<!-- /wp:heading -->','Gépészeti alapismeretek','','inherit','closed','closed','','19-revision-v1','','','2024-06-21 11:31:03','2024-06-21 09:31:03','',19,'http://192.168.188.6/timara/?p=271',0,'revision','',0);
